typedef struct otc_cp_JsonValue otc_cp_JsonValue;
typedef struct otc_cp_JsonPair { const char *key; const otc_cp_JsonValue *value; } otc_cp_JsonPair;
typedef enum otc_cp_JsonTag { OTC_CP_JSON_NULL, OTC_CP_JSON_BOOLEAN, OTC_CP_JSON_NUMBER, OTC_CP_JSON_STRING, OTC_CP_JSON_ARRAY, OTC_CP_JSON_OBJECT } otc_cp_JsonTag;
struct otc_cp_JsonValue { otc_cp_JsonTag tag; union { bool boolean; double number; struct { const char *bytes; size_t count; } string; struct { const otc_cp_JsonValue *items; size_t count; } array; struct { const otc_cp_JsonPair *entries; size_t count; } members; } value; };

